INSERT INTO `bonk_tier_locale` (`id`, `locale`, `name`, `description`, `details`)
VALUES
  (1, 'zhCN', '普通', '在开阔的地带挑战一个阶段。通关普通4级即可开启英雄难度。', '首领的法术略有预判。^精英带有1个词缀。'),
  (2, 'zhCN', '史诗', '在最致命的强敌面前挑战三个阶段。每个史诗级别都更加艰难，回报也更丰厚，而且永远还有下一级。获得的专精经验值提高100%。', '敌人的生命值提高220%，造成的伤害提高60%，且每个级别都会继续提高。^施法者的射击会精确预判。^首领的法术会精确预判，并获得更多攻击手段。^25%的敌人是老兵：更强悍，奖励也更高。^精英带有3个词缀。冲锋者冲锋更频繁。'),
  (3, 'zhCN', '英雄', '在更凶险的地带挑战两个阶段，敌人更强，战利品更好，暗月奖券更多，专精经验值提高50%。通关英雄5级即可开启史诗难度。', '敌人的生命值提高60%，造成的伤害提高30%。^施法者的射击预判更准一些。^首领的法术预判更多，并获得额外的攻击手段。^15%的敌人是老兵：更强悍，奖励也更高。^精英带有2个词缀。冲锋者冲锋更频繁。');
